import sys

def find_typos(dictionary):
    typos = []
    for i in range(len(dictionary)):
        original_word = dictionary[i]
        for j in range(len(original_word)):
            candidate_word = original_word[:j] + original_word[j+1:]
            if candidate_word in dictionary and candidate_word != original_word:
                typos.append(original_word)
                break
    return typos

