def find_typos(dictionary):
    def is_typo(word, dictionary):
        for i in range(len(word)):
            candidate = word[:i] + word[i+1:]
            if candidate in dictionary:
                return True
        return False

    typos = []
    for word in dictionary:
        if is_typo(word, dictionary):
            typos.append(word)

    return typos

